#include <iostream>
#include <cassert>
struct Data { int value; };
int main() {
  Data data{10};
  char* pc = reinterpret_cast<char*>(&data);
  // Accessing the underlying bytes; potentially dangerous unless you know the structure's layout!
  std::cout << *pc << std::endl; // Accessing the first byte.
  //Note that the following might result in undefined behavior if alignment isn't properly handled
  int* pi = reinterpret_cast<int*>(pc + sizeof(int)); // Incorrect usage unless very careful about data layout.
  // Safer alternative with explicit size and offset would be needed
  return 0;
}
